      <p class="intro">Choose how you prefer to receive notifications, then submit your selection.</p>

      <form id="notification-form" novalidate>
        <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

        <div class="form-field">
          <fieldset id="notification-group" aria-describedby="notification-help">
            <legend>How do you prefer to receive notifications? <span class="legend-required" aria-hidden="true">*</span></legend>
            <p class="field-help" id="notification-help">Select exactly one option.</p>
            <p class="field-error" id="notification-error" hidden>Error: Select one notification method before submitting.</p>

            <div class="radio-list">
              <div class="radio-option">
                <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                <label for="notification-email">Email</label>
              </div>

              <div class="radio-option">
                <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
                <label for="notification-sms">SMS</label>
              </div>

              <div class="radio-option">
                <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                <label for="notification-push">Push Notifications</label>
              </div>
            </div>
          </fieldset>
        </div>

        <button type="submit">Submit preference</button>
        <p id="form-status" class="status-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const fieldset = document.getElementById('notification-group');
    const radios = Array.from(form.elements.notificationPreference);
    const errorMessage = document.getElementById('notification-error');
    const statusMessage = document.getElementById('form-status');
    const helpIds = ['notification-help'];

    function setDescribedBy(ids) {
      fieldset.setAttribute('aria-describedby', ids.join(' '));
    }

    function clearValidationState() {
      errorMessage.hidden = true;
      setDescribedBy(helpIds);
      statusMessage.textContent = '';
      statusMessage.dataset.state = '';

      radios.forEach((radio) => {
        radio.removeAttribute('aria-invalid');
      });
    }

    function showError() {
      errorMessage.hidden = false;
      setDescribedBy([...helpIds, 'notification-error']);
      statusMessage.textContent = 'Please select a notification method.';
      statusMessage.dataset.state = 'error';

